// Normalize the worker_soar identity step and select the IdP API by environment.
const body = $input.first().json.body || $input.first().json;
const env = (body.environment || 'local').toLowerCase();
const action = body.action || 'disable_user';
const urls = {
  entra: $env.ENTRA_GRAPH_URL,
  iam:   $env.AWS_IAM_GATEWAY_URL,
  gcp:   $env.GCP_IAM_GATEWAY_URL,
  local: $env.AD_CONTAINMENT_WEBHOOK_URL,
};
return [{ json: {
  incident_id: body.incident_id || 'UNKNOWN',
  environment: env,
  target: body.target || '',
  action: action,
  api_url: urls[env] || urls.local,
  api_body: JSON.stringify({ incident_id: body.incident_id, environment: env, principal: body.target, action }),
} }];
